package ch.piiwii.roadbookgeneve;
import android.app.*;import android.content.*;import android.os.Build;
public class AlarmReceiver extends BroadcastReceiver{public static final String CHANNEL_ID="roadbook_alerts";public void onReceive(Context c,Intent i){createChannel(c);String t=i.getStringExtra("title"),x=i.getStringExtra("text");int id=i.getIntExtra("notification_id",42);PendingIntent pi=PendingIntent.getActivity(c,id,new Intent(c,MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL_ID):new Notification.Builder(c);b.setSmallIcon(R.drawable.ic_notification).setContentTitle(t==null?"Roadbook Genève":t).setContentText(x==null?"Il est temps de bouger.":x).setStyle(new Notification.BigTextStyle().bigText(x)).setContentIntent(pi).setAutoCancel(true).setCategory(Notification.CATEGORY_REMINDER).setPriority(Notification.PRIORITY_HIGH);NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(n!=null)n.notify(id,b.build());}public static void createChannel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(n!=null){NotificationChannel ch=new NotificationChannel(CHANNEL_ID,"Rappels Roadbook",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Rappels de départ et horaires importants de la journée Genève.");ch.enableVibration(true);n.createNotificationChannel(ch);}}}}
